// TH15 v1.00b Stage 5 mid-stage, MainSub07 first half (st05.ecl.txt:1598-1610).
// Girls: st05.ecl.txt:466-492 (GirlA05/GirlA05_at) and 494-537 (GirlA05_at2).
// Source bullet type 8 -> TH15_RICE (transcribe/th15/touhou-bullets.ecl).

const TH15_RICE: int = 480;

const TIME_LIMIT: int = 1324;
const OPENING_BUFFER: int = 120;

// Source EX LASER (a=0 Line): line length 32, native width 16 (w<32 => half = w/4 = 4).
// Judgment segment skips L/10 and is 0.8L long; target lasers have one constant width.
const LASER_COLOR: int = 13;
const LASER_JUDGE_OFFSET: fx = 3.2fx;
const LASER_JUDGE_LEN: fx = 25.6fx;
const LASER_JUDGE_WIDTH: fx = 8fx;
const LASER_LEN_LIMIT: int = 128;
// Source EX ANIM a=1 birth displacement: position -= 4*speed along own angle (speed 1.0).
const BULLET_BIRTH_SHIFT: fx = -4fx;
// Source VELTIME gate: the LASER record runs once the 60-frame ramp finishes.
const BULLET_LASER_DELAY: int = 60;

// Source etEx records 0-2 (ANIM/BRIGHT/VELTIME) are folded into: rice bullet flies 60
// frames at speed 1.0, then is deleted while the line laser takes over (LASER d=1).
xformdef BULLET_UNTIL_LASER {
    wait(BULLET_LASER_DELAY);
    set_life(1);
}

// Source EX LASER line: origin = bullet position, angle = bullet angle (r preserves),
// speed 4/6/8/10 by difficulty, parent deleted. Target laser grows a rod then travels;
// travel is cut at the source lengthLimit (n=128) by the active timer.
async sub line_laser() {
    // bullet task starts one frame after birth; 59 => laser at source's 60th frame.
    wait(BULLET_LASER_DELAY - 1);
    var rank: int = global(GVAR_RANK);
    var spd: fx = (4 + rank * 2) as fx;
    var active: int = LASER_LEN_LIMIT / (4 + rank * 2);
    var dir: angle = $self_angle;
    var h: int = laser(LASER_COLOR,
        $self_x + LASER_JUDGE_OFFSET * cos(dir),
        $self_y + LASER_JUDGE_OFFSET * sin(dir),
        dir, 0fx, LASER_JUDGE_WIDTH, 0, active, 0);
    if h >= 0 {
        lz_speed(h, spd, LASER_JUDGE_LEN);
    }
}

// GirlA05_at2 (494-537): aim mode 3 fixed ring, rice sprite (8,13), one speed layer,
// ring ways 5 on Easy and 8 otherwise, 80 waves every 80 frames, alpha = 90deg +/- 15deg.
async sub girl_fire() {
    var ways: int = 8;
    if global(GVAR_RANK) == 0 {
        ways = 5;
    }
    sh_reset(0);
    sh_sprite(0, TH15_RICE, 13);
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_count(0, ways, 1);
    sh_speed(0, 1fx, 0fx);
    sh_dist(0, BULLET_BIRTH_SHIFT);
    sh_xform(0, BULLET_UNTIL_LASER);
    sh_task(0, line_laser);
    wait(10 + rand(40));            // 497: wait(10 + RAND%40)
    for wave in 0..80 {             // 517/535: $B = 80, if ($B--) ...
        var off: int = ((rand(65536) - 32768) * 2731) / 32768;  // RANDF2 * 15deg
        sh_angle(0, 90deg + (off as angle), 0deg);
        sh_fire(0);
        wait(80);
    }
}

// GirlA05 (466-475) + GirlA05_at (477-492).
// enmCreateM mirror is expressed by mirroring the velocity angles for the +x copy.
async sub girl_body(mirror: int, f0: angle) {
    set_invuln(65535);
    set_hurtbox(12fx);              // 479: setHurtbox(24,24) -> radius 12
    set_hitbox(8fx);                // 480: setHitbox(16,16) -> radius 8
    spawn girl_fire();              // 481: @GirlA05_at2() async
    var a0: angle = f0;             // 482: moveVel(F0, 3.0)
    var a1: angle = 0deg - 11.25deg; // 483: moveVelTime(120,1,-0.19634955,2.0)
    var a2: angle = 45deg;          // 485: moveVelTime(60,4,0.7853982,4.0)
    if mirror != 0 {
        a0 = 180deg - f0;
        a1 = 180deg - a1;
        a2 = 180deg - a2;
    }
    move_vel(0, a0, 3fx, EASE_LINEAR);
    move_vel(120, a1, 2fx, EASE_QUAD_IN);
    wait(120);
    move_vel(60, a2, 4fx, EASE_QUAD_OUT);
    wait(60);
    // Source enemy ends with an infinite wait; the native game culls it offscreen.
    // The fairy enters from x=+/-224, so it is inside while the two ramps run; leave
    // as soon as it has crossed the +/-224 (and y -32..480) envelope again.
    loop {
        var x: fx = $self_x;
        var y: fx = $self_y;
        if x <= -224fx || x >= 224fx || y <= -32fx || y >= 480fx {
            return;
        }
        wait(1);
    }
}

// MainSub07 first half (1598-1610): wait(80), 24 rounds of two GirlA05 every 20 frames.
// %F0 is drawn once per round and inherited by both children.
async sub pattern() {
    wait(OPENING_BUFFER);
    wait(80);
    for round in 0..24 {
        var u: int = rand(65536) - 32768;
        var f0: angle = 4096bam + ((u * 3641) / 32768) as angle; // 0.3926991 + RANDF2*0.34906584
        var yl: fx = 64fx + (((rand(65536) - 32768) as fx) / 32768) * 32fx;
        _ = spawn_enemy(-224fx, yl, 50, 0, 1000, 0, girl_body(0, f0));
        var yr: fx = 64fx + (((rand(65536) - 32768) as fx) / 32768) * 32fx;
        _ = spawn_enemy(224fx, yr, 50, 0, 1000, 0, girl_body(1, f0));
        wait(20);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
